// Shell screens connected to the session and to Expo Router.
import { useRouter, type Href } from 'expo-router';
import { useSession } from '../auth/session';
import { MyInstitutionsScreen } from '../institutions/MyInstitutionsScreen';
import { ProfilePlaceholder } from './ProfilePlaceholder';
import { ShellPlaceholder } from './ShellPlaceholder';
import { SHELL_TABS, type ShellName } from './shells';

// Typed routes (.expo/types) are generated by `expo start`; these paths exist under src/app/(app).
const MY_INSTITUTIONS = '/institutions' as Href;
const SETTINGS = '/settings' as Href;
const REGISTER_INSTITUTION = '/register-institution' as Href;
const joinSectionHref = (code: string) => `/join-section?code=${encodeURIComponent(code)}` as Href;

/** Placeholder of a tab that is not built yet. */
export function TabPlaceholder({ shell, tab }: { shell: ShellName; tab: string }) {
  const found = SHELL_TABS[shell].find((t) => t.key === tab);
  if (!found) return null;
  return <ShellPlaceholder title={found.title} screens={found.screens} />;
}

/** Perfil (21) of every shell. */
export function ProfileRoute() {
  const { user, signOut } = useSession();
  const router = useRouter();
  if (!user) return null;
  return (
    <ProfilePlaceholder
      user={user}
      onOpenInstitutions={() => router.push(MY_INSTITUTIONS)}
      onOpenSettings={() => router.push(SETTINGS)}
      onSignOut={() => signOut()}
    />
  );
}

/** Ajustes y cuenta (23), pushed from Perfil. */
export function SettingsRoute() {
  const router = useRouter();
  return <ShellPlaceholder title="Ajustes y cuenta" screens={[23]} onBack={() => router.back()} />;
}

/**
 * Mis instituciones (22) pushed from another screen, with one row per role: choosing a row makes that
 * institution and role the active view and goes back, so the shell underneath follows the new view.
 */
export function InstitutionsRoute() {
  const { user, signupChoice, activeInstitutionId, activeRole, setActiveInstitution, joinInstitution } = useSession();
  const router = useRouter();
  if (!user) return null;
  return (
    <MyInstitutionsScreen
      user={user}
      activeInstitutionId={activeInstitutionId}
      activeRole={activeRole}
      signupChoice={signupChoice}
      onSelect={async (institutionId, role) => {
        await setActiveInstitution(institutionId, role);
        if (router.canGoBack()) router.back();
      }}
      onJoinInstitution={joinInstitution}
      onSectionCode={(code) => router.push(joinSectionHref(code))}
      onRegisterInstitution={() => router.push(REGISTER_INSTITUTION)}
      onBack={() => router.back()}
    />
  );
}
